    32→# Test Constant node execution
    33→subtest 'Constant node execution' => sub {
    34→    # Create a simple Constant node
    35→    my $constant = Chalk::IR::Node::Constant->new(
    36→        id => 'node_1',
    37→        inputs => ['node_0'],
    38→        value => 42,
    39→        type => 'Int',
    40→    );
    41→
    42→    # Execute should return the constant value
    43→    my $result = $constant->execute();
    44→    is($result, 42, 'Constant node execute returns its value');
    45→};
