   385→# Test graph linearization with data dependencies
   386→subtest 'Graph linearization with arithmetic: (3 + 5) * 2' => sub {
   387→    my $graph = Chalk::IR::Graph->new();
   388→
   389→    # Start node
   390→    my $start = Chalk::IR::Node::Start->new(
   391→        id => 'node_0',
   392→        inputs => [],
   393→        function_name => 'main',
   394→        params => [],
   395→    );
   396→    $graph->add_node($start);
   397→
   398→    # Constants: 3, 5, 2
   399→    my $const3 = Chalk::IR::Node::Constant->new(
   400→        id => 'node_1',
   401→        inputs => ['node_0'],
   402→        value => 3,
   403→        type => 'Int',
   404→    );
   405→    $graph->add_node($const3);
   406→
   407→    my $const5 = Chalk::IR::Node::Constant->new(
   408→        id => 'node_2',
   409→        inputs => ['node_0'],
   410→        value => 5,
   411→        type => 'Int',
   412→    );
   413→    $graph->add_node($const5);
   414→
   415→    # Add: 3 + 5
   416→    my $add = Chalk::IR::Node::Add->new(
   417→        id => 'node_3',
   418→        inputs => ['node_0', 'node_1', 'node_2'],
   419→        left_id => 'node_1',
   420→        right_id => 'node_2',
   421→    );
   422→    $graph->add_node($add);
   423→
   424→    my $const2 = Chalk::IR::Node::Constant->new(
   425→        id => 'node_4',
   426→        inputs => ['node_0'],
   427→        value => 2,
   428→        type => 'Int',
   429→    );
   430→    $graph->add_node($const2);
   431→
   432→    # Multiply: (3 + 5) * 2
   433→    my $mul = Chalk::IR::Node::Multiply->new(
   434→        id => 'node_5',
   435→        inputs => ['node_0', 'node_3', 'node_4'],
   436→        left_id => 'node_3',
   437→        right_id => 'node_4',
   438→    );
   439→    $graph->add_node($mul);
   440→
   441→    # Return
   442→    my $return = Chalk::IR::Node::Return->new(
   443→        id => 'node_6',
   444→        inputs => ['node_0', 'node_5'],
   445→        value_id => 'node_5',
   446→        control_id => 'node_0',
   447→    );
   448→    $graph->add_node($return);
   449→
   450→    # Linearize the graph
   451→    my @schedule = $graph->linearize();
   452→
   453→    # Verify we have all 7 nodes
   454→    is(scalar(@schedule), 7, 'Linearization includes all 7 nodes');
   455→
   456→    # Build position map
   457→    my %positions;
   458→    for my $i (0..$#schedule) {
   459→        $positions{$schedule[$i]->id} = $i;
   460→    }
   461→
   462→    # Verify Start is first
   463→    is($positions{'node_0'}, 0, 'Start is first');
   464→
   465→    # Verify constants before Add
   466→    ok($positions{'node_1'} < $positions{'node_3'}, 'Constant(3) before Add');
   467→    ok($positions{'node_2'} < $positions{'node_3'}, 'Constant(5) before Add');
   468→
   469→    # Verify Add and Constant(2) before Multiply
   470→    ok($positions{'node_3'} < $positions{'node_5'}, 'Add before Multiply');
   471→    ok($positions{'node_4'} < $positions{'node_5'}, 'Constant(2) before Multiply');
   472→
   473→    # Verify Multiply before Return
   474→    ok($positions{'node_5'} < $positions{'node_6'}, 'Multiply before Return');
   475→};
