     1→# ABOUTME: End-to-end integration test for Parser → Builder → Interpreter pipeline
     2→# ABOUTME: Verifies Chalk can parse, build IR, and execute simple programs
     3→
     4→use v5.42;
     5→use Test::More;
     6→
     7→# Load all required modules
     8→use_ok('Chalk::Parser');
