    11→use_ok('Chalk::IR::Builder');
    12→use_ok('Chalk::IR::Interpreter');
    13→use_ok('Chalk::IR::Optimizer::GVN');
    14→
    15→# Load Chalk grammar from BNF file
    16→open my $fh, '<:utf8', 'grammar/chalk.bnf' or die "Cannot open chalk.bnf: $!";
    17→my $bnf_content = do { local $/; <$fh> };
    18→close $fh;
    19→my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program', 'Chalk');
    20→
    21→# Test 1: Simple arithmetic with variable
    22→subtest 'Execute: my $x = 3 + 5; return $x * 2;' => sub {
    23→    # Step 1: Create Builder
    24→    my $builder = Chalk::IR::Builder->new();
    25→
    26→    # Step 2: Create Parser with semantic actions that build IR
    27→    my $semiring = Chalk::Semiring::Semantic->new(
    28→        grammar => $grammar,
    29→        env => { ir_builder => $builder }
    30→    );
    31→
    32→    my $parser = Chalk::Parser->new(
    33→        grammar => $grammar,
    34→        semiring => $semiring,
    35→        preprocess => ['Chalk::Preprocessor::Heredoc']
    36→    );
    37→
    38→    # Step 3: Parse the program
    39→    my $code = 'my $x = 3 + 5; return $x * 2;';
    40→    my $parse_result = $parser->parse_string($code);
    41→    ok($parse_result, 'Program parses successfully');
    42→
    43→    # Step 4: Get the IR graph
    44→    my $graph = $builder->graph;
