        # First node added becomes entry point
        $entry //= $node_id;

        return;
    }

    method get_node($id) {
        return $nodes->{$id};
    }

    method get_uses($id) {
        return $uses->{$id} // [];
    }

    method node_count() {
        return scalar keys %{$nodes};
    }

