    test_against_perl('return 10 - 3;', 'Simple subtraction: 10 - 3');
    test_against_perl('return 5 - 5;', 'Subtraction resulting in zero');
    test_against_perl('return 3 - 10;', 'Subtraction resulting in negative');
};

