# ABOUTME: Semantic action for Unary - pass through child value or build unary operation
# ABOUTME: Unary handles prefix operators like !, -, +, \, building appropriate IR nodes

use 5.42.0;
use experimental 'class';
use Scalar::Util 'blessed';

class Chalk::Grammar::Chalk::Rule::Unary :isa(Chalk::GrammarRule) {
    method evaluate($context) {
        # ExprUnary -> ExprPower (pass-through)
        # ExprUnary -> OpUnary WS_OPT ExprUnary (unary operation)
        #   Where OpUnary can be: !, -, +, ~, \

        my @children = $context->children->@*;
        warn "DEBUG Unary::evaluate: children count=" . scalar(@children) . "\n";
        for my $i (0 .. $#children) {
            my $child = $children[$i];
            my $extracted = $child->extract;
            warn "DEBUG Unary::evaluate:   child($i) = " . (defined($extracted) ? (ref($extracted) || "'$extracted'") : 'undef') . "\n";
        }

        if (@children == 1) {
            # First alternative: just pass through ExprPower
            warn "DEBUG Unary::evaluate: 1 child, pass-through\n";
            return $context->child(0);
        }

        # For unary operation: check child(0) for the operator
        my $op_child = $children[0]->extract;
        warn "DEBUG Unary::evaluate: op_child=" . (defined($op_child) ? (ref($op_child) || "'$op_child'") : 'undef') . "\n";

        unless (defined $op_child && !ref($op_child)) {
            warn "DEBUG Unary::evaluate: early return - op_child not defined or is ref\n";
            return $context->child(0);
        }

        my $operator = $op_child;
        my $builder = $context->env->{ir_builder};
        warn "DEBUG Unary::evaluate: operator='$operator', builder=" . (defined($builder) ? ref($builder) : 'undef') . "\n";

        unless ($builder) {
            warn "DEBUG Unary::evaluate: early return - no builder\n";
            return $context->child(0);
        }

        # Get operand (child 1, WS_OPT is collapsed when empty)
        my $operand = $context->child(1);
        warn "DEBUG Unary::evaluate: operand=" . (defined($operand) ? (ref($operand) || $operand) : 'undef') . "\n";

        # Validate that we got an IR node
        unless (blessed($operand) && $operand->can('id')) {
            warn "DEBUG Unary::evaluate: early return - operand not an IR node\n";
            return $operand;
        }

        # Build appropriate unary node
        warn "DEBUG Unary::evaluate: building node for operator '$operator'\n";
        if ($operator eq '!') {
            my $not_node = $builder->build_not_node($operand);
            warn "DEBUG Unary::evaluate: created Not node " . $not_node->id . "\n";
            return $not_node;
