use v5.42;
use lib 'lib';
use Chalk::Parser;
use Chalk::Grammar;
use Chalk::Semiring::Semantic;
use Chalk::IR::Builder;
use Chalk::IR::Interpreter;
use Chalk::IR::Optimizer::GVN;

open my $fh, '<:utf8', 'grammar/chalk.bnf' or die;
my $bnf_content = do { local $/; <$fh> };
close $fh;
my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program', 'Chalk');

my $code = 'return !0;';
print "Testing: $code\n";

my $builder = Chalk::IR::Builder->new();
my $semiring = Chalk::Semiring::Semantic->new(
    grammar => $grammar,
    env => { ir_builder => $builder }
);
my $parser = Chalk::Parser->new(
    grammar => $grammar,
    semiring => $semiring,
    preprocess => ['Chalk::Preprocessor::Heredoc']
);

my $parse_result = $parser->parse_string($code);
my $graph = $builder->graph;

print "\nBefore pruning: " . scalar(keys %{$graph->nodes}) . " nodes\n";

# Prune using parse result
if ($parse_result->can('context')) {
    my $ctx = $parse_result->context;
    if ($ctx->can('focus')) {
        my $winning_node = $ctx->focus;
        if ($winning_node && $winning_node->can('id')) {
            print "Winning node: " . $winning_node->id . " (" . $winning_node->op . ")\n";
            $graph->prune_to_reachable($winning_node->id);
        }
    }
}

print "\nAfter pruning: " . scalar(keys %{$graph->nodes}) . " nodes\n";
for my $id (sort keys %{$graph->nodes}) {
    my $node = $graph->nodes->{$id};
    print "  $id: " . ref($node) . " (" . $node->op . ")\n";
}

# Run GVN
my $gvn_result = Chalk::IR::Optimizer::GVN->run_gvn($graph);
$graph = $gvn_result->{graph};

print "\nAfter GVN: " . scalar(keys %{$graph->nodes}) . " nodes\n";
for my $id (sort keys %{$graph->nodes}) {
    my $node = $graph->nodes->{$id};
    print "  $id: " . ref($node) . " (" . $node->op . ")\n";
}

# Execute
eval {
    my $interpreter = Chalk::IR::Interpreter->new(graph => $graph);
    my $result = $interpreter->execute();
