use v5.42;
use lib 'lib';
use Chalk::Parser;
use Chalk::Grammar;
use Chalk::Semiring::Semantic;
use Chalk::IR::Builder;

# Patch Parser::complete to show which elements are being compared
{
    no warnings 'redefine';
    my $orig_complete = \&Chalk::Parser::complete;

    *Chalk::Parser::complete = sub {
        my ($self, $completed_item, $completed_element, $chart, $agenda) = @_;

        my $lhs = $completed_item->rule->lhs;

        # Check for Return statement completions
        if ($lhs eq 'ReturnStatement') {
            print "\n=== RETURN STATEMENT COMPLETION ===\n";
            print "completed_element focus: ";
            if ($completed_element->context->focus) {
                my $f = $completed_element->context->focus;
                print ref($f) . " (id=" . ($f->can('id') ? $f->id : 'N/A') . ")";
            } else {
                print "undef";
            }
            print "\n";
            print "completed_element span: " . ($completed_element->context->end_pos - $completed_element->context->start_pos) . "\n";
            print "completed_element children: " . scalar(@{$completed_element->context->children}) . "\n";
        }

        return $orig_complete->(@_);
    };
}

open my $fh, '<:utf8', 'grammar/chalk.bnf' or die;
my $bnf_content = do { local $/; <$fh> };
close $fh;

my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program', 'Chalk');

my $code = 'return !0;';
print "Parsing: $code\n";

my $builder = Chalk::IR::Builder->new();
my $semiring = Chalk::Semiring::Semantic->new(
    grammar => $grammar,
    env => { ir_builder => $builder }
);
my $parser = Chalk::Parser->new(
    grammar => $grammar,
    semiring => $semiring,
    preprocess => ['Chalk::Preprocessor::Heredoc']
);

my $parse_result = $parser->parse_string($code);

print "\n=== FINAL RESULT ===\n";
if ($parse_result->can('context')) {
    my $ctx = $parse_result->context;
    if ($ctx->can('focus')) {
        my $winning_node = $ctx->focus;
        if ($winning_node) {
            print "Winning node: " . $winning_node->id . " (" . $winning_node->op . ")\n";
        } else {
            print "Winning node focus: undef\n";
        }
    }
}

