use v5.42;
use lib 'lib';
use Chalk::Parser;
use Chalk::Grammar;
use Chalk::Semiring::Semantic;
use Chalk::IR::Builder;
use Scalar::Util 'blessed';

# Patch ReturnStatement to log what it's doing
{
    no warnings 'redefine';
    my $orig_eval = \&Chalk::Grammar::Chalk::Rule::ReturnStatement::evaluate;

    *Chalk::Grammar::Chalk::Rule::ReturnStatement::evaluate = sub {
        my ($self, $context) = @_;

        my @children = $context->children->@*;
        print "\n=== RETURN STATEMENT EVALUATE ===\n";
        print "Children count: " . scalar(@children) . "\n";

        for my $i (0 .. $#children) {
            my $child_ctx = $children[$i];
            my $child_focus = $child_ctx->focus if $child_ctx;
            print "  child($i) focus: ";
            if (!defined($child_focus)) {
                my $extracted = $child_ctx->extract;
                print defined($extracted) && !ref($extracted) ? "'$extracted'" : (ref($extracted) || 'undef');
            } elsif (ref($child_focus) && $child_focus->can('id')) {
                print ref($child_focus) . " (id=" . $child_focus->id . ", op=" . $child_focus->op . ")";
            } else {
                print ref($child_focus) || "'$child_focus'";
            }
            print "\n";
        }

        my $result = $orig_eval->(@_);
        print "Result: ";
        if (!defined($result)) {
            print "undef\n";
        } elsif (ref($result) && $result->can('id')) {
            print ref($result) . " (id=" . $result->id . ", op=" . $result->op . ")";
            if ($result->can('inputs')) {
                my @inputs = $result->inputs->@*;
                print " inputs=[" . join(", ", @inputs) . "]";
            }
            print "\n";
        } else {
            print ref($result) || "'$result'\n";
        }

        return $result;
    };
}

open my $fh, '<:utf8', 'grammar/chalk.bnf' or die;
my $bnf_content = do { local $/; <$fh> };
close $fh;

my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program', 'Chalk');

my $code = 'return !0;';
print "Parsing: $code\n";

my $builder = Chalk::IR::Builder->new();
my $semiring = Chalk::Semiring::Semantic->new(
    grammar => $grammar,
    env => { ir_builder => $builder }
);
my $parser = Chalk::Parser->new(
    grammar => $grammar,
    semiring => $semiring,
    preprocess => ['Chalk::Preprocessor::Heredoc']
);

my $parse_result = $parser->parse_string($code);
print "\n=== DONE ===\n";

