method evaluate($context) {
    # ReturnStatement can have multiple forms:
    # ReturnStatement -> 'return'
    # ReturnStatement -> 'return' WS_OPT Expression
    # ReturnStatement -> 'return' WS_OPT '(' WS_OPT ExpressionList WS_OPT ')'
    # NOTE: WS_OPT is collapsed when empty, so child count varies

    my $builder = $context->env->{ir_builder};
    return undef unless $builder;

    my @children = $context->children->@*;

    # For bare "return;" (1 child), return undef for now
    return undef if @children == 1;

    # For "return Expression" form:
    # - If WS_OPT collapsed (no whitespace): 2 children, expr at child(1)
    # - If WS_OPT present (with whitespace): 3 children, expr at child(2)
    # For "return (...)" form: more children
    my $expr_node;
    if (@children == 2) {
        # WS_OPT collapsed: 'return' Expression
        $expr_node = $context->child(1);
    } else {
        # WS_OPT present or complex form: check child(2)
        $expr_node = $context->child(2);
    }

    # Build Return IR node WITHOUT control assignment
    # The control input will be '__CONTROL_PLACEHOLDER__'
    # Parent rule (Block, ConditionalStatement, etc) must wire up control
    return undef unless $expr_node;

    return $builder->build_return_node($expr_node, '__CONTROL_PLACEHOLDER__');
}

