sub execute_perl {
    my ($code) = @_;

    # Wrap code in a subroutine so 'return' works
    my $wrapped_code = "use v5.42;\nsub main { $code }\nmy \$result = main();\nprint \$result;\n";

    # Create temporary file
    my $tmpfile = File::Temp->new(SUFFIX => '.pl');
    print $tmpfile $wrapped_code;
