use Chalk::IR::Node::Proj;
use Chalk::IR::Node::Return;
use Chalk::IR::Node::Store;
use Chalk::IR::Node::Load;

class Chalk::IR::Node {
    field $id           :param :reader;
    field $op           :param :reader;
    field $inputs       :param :reader;
    field $attributes   :param :reader;

