     1→# ABOUTME: Semantic semiring for building values during parsing with evaluation contexts
     2→# ABOUTME: Tracks contexts and enables semantic actions via EvalContext comonad
     3→
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→use Chalk::Base;
     8→use Chalk::EvalContext;
     9→use Chalk::Type::Int;
    10→use Chalk::Type::Num;
    11→use Chalk::Type::Str;
    12→use Chalk::Type::Scalar;
    13→use Chalk::Type::Array;
    14→use Chalk::Type::Hash;
    15→use Chalk::Type::List;
    16→use Chalk::Type::Any;
    17→
    18→class Chalk::Semiring::SemanticElement :isa(Chalk::Element) {
    19→    field $value :param :reader;         # Computed semantic value
    20→    field $context :param :reader;       # Evaluation context
    21→    field $sppf_node :param = undef;     # Optional SPPF node
    22→
    23→    method add( $other, $swap = undef ) {
    24→        # For alternatives (choice), prefer non-zero value
    25→        # If self has value 0 (is add_id), return other
    26→        if ($value == 0) {
    27→            return $other;
    28→        }
    29→
    30→        # Prefer elements with evaluated focus (defined) over unevaluated (undef)
    31→        # This handles the case where we update the chart after evaluation
    32→        my $self_focus = $self->context->focus;
    33→        my $other_focus = $other->context->focus;
    34→
    35→        if (!defined($self_focus) && defined($other_focus)) {
    36→            return $other;
    37→        }
    38→        if (defined($self_focus) && !defined($other_focus)) {
    39→            return $self;
    40→        }
    41→
    42→        # For semantic values, prefer the alternative that consumed more input
    43→        # (this handles ambiguous parses - longer parse is more complete)
    44→        # Use parse span (end_pos - start_pos) as primary ranking
    45→        my $self_span = $self->context->end_pos - $self->context->start_pos;
    46→        my $other_span = $other->context->end_pos - $other->context->start_pos;
    47→
    48→        if ($other_span > $self_span) {
    49→            return $other;  # Other consumed more input, prefer it
    50→        }
    51→        if ($self_span > $other_span) {
    52→            return $self;  # Self consumed more input, prefer it
    53→        }
    54→
    55→        # If spans are equal, prefer the alternative with more children
    56→        # (handles cases where both consumed same input but one has more structure)
    57→        my $self_children = scalar(@{$self->context->children});
    58→        my $other_children = scalar(@{$other->context->children});
    59→
    60→        if ($other_children > $self_children) {
    61→            return $other;
    62→        }
    63→
    64→        # Otherwise prefer self (first alternative)
    65→        return $self;
    66→    }
    67→
    68→    method multiply( $other, $swap = undef ) {
    69→        # For sequences, append other's context to self's children
    70→        # This builds up the children list as we advance the dot through the rule
    71→        my @new_children = (@{$self->context->children}, $other->context);
    72→
    73→        # Type propagation: keep the type from self's context (the rule being built)
    74→        my $combined_ctx = Chalk::EvalContext->new(
    75→            focus => undef,  # Not yet evaluated
    76→            children => \@new_children,
    77→            start_pos => $self->context->start_pos,
    78→            end_pos => $other->context->end_pos,
    79→            env => $self->context->env,
    80→            grammar => $self->context->grammar,
    81→            rule => $self->context->rule,
    82→            forest => $self->context->forest,
    83→            type => $self->context->type  # Propagate type from rule
    84→        );
    85→
    86→        return Chalk::Semiring::SemanticElement->new(
    87→            value => 1,  # Success value
    88→            context => $combined_ctx,
    89→            sppf_node => $sppf_node
    90→        );
    91→    }
    92→
    93→    method equals( $other, $swap = undef ) {
    94→        return 0 unless ref($other) eq ref($self);
    95→        # Use refaddr for reference equality to avoid recursion
    96→        # For semantic semiring, we want elements to be considered non-equal
    97→        # to add_id unless they are literally the same object
    98→        return refaddr($self) == refaddr($other) ? 1 : 0;
    99→    }
   100→
   101→    method score() {
   102→        # Semantic semiring doesn't use numeric scores
   103→        return 1;
   104→    }
   105→
   106→    method to_string(@args) {
   107→        # Return value (0 for add_id, 1 for others) for Parser's numeric comparisons
   108→        return defined($value) ? "$value" : '1';
   109→    }
   110→}
   111→
   112→class Chalk::Semiring::Semantic :isa(Chalk::Semiring) {
   113→    field $env :param = {};
   114→    field $grammar :param :reader;
   115→    field $shared_context :param :reader = undef;
   116→    field $type_env :param :reader = {};  # Maps variable names to Chalk::Type objects
   117→    field $forest :reader;
   118→    field $mul_id :reader;
   119→    field $add_id :reader;
   120→    field $_add_id_is_zero :reader = 1;  # Flag to identify add_id
   121→
   122→    ADJUST {
   123→        # Store reference to shared forest if provided
   124→        $forest = defined($shared_context) && exists($shared_context->{forest})
   125→            ? $shared_context->{forest}
   126→            : undef;
   127→
   128→        # Create identity elements with empty contexts
   129→        my $empty_ctx_mul = Chalk::EvalContext->new(
   130→            focus => undef,
   131→            children => [],
   132→            start_pos => 0,
   133→            end_pos => 0,
   134→            env => $env,
   135→            grammar => $grammar,
   136→            rule => undef,
   137→            forest => $forest
   138→        );
   139→
   140→        my $empty_ctx_add = Chalk::EvalContext->new(
   141→            focus => undef,
   142→            children => [],
   143→            start_pos => 0,
   144→            end_pos => 0,
   145→            env => $env,
   146→            grammar => $grammar,
   147→            rule => undef,
   148→            forest => $forest
   149→        );
   150→
   151→        $mul_id = Chalk::Semiring::SemanticElement->new(
   152→            value => 1,  # mul_id has value 1
   153→            context => $empty_ctx_mul
   154→        );
   155→
   156→        $add_id = Chalk::Semiring::SemanticElement->new(
   157→            value => 0,  # add_id has value 0 (failure/no parse)
   158→            context => $empty_ctx_add
   159→        );
   160→    }
   161→
   162→    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0, $parent_derivation_id = undef) {
   163→        # Infer type from the rule
   164→        my $inferred_type = $self->infer_type_from_rule($rule);
   165→
   166→        my $ctx = Chalk::EvalContext->new(
   167→            focus => undef,
   168→            children => [],
   169→            start_pos => $start_pos,
   170→            end_pos => $end_pos,
   171→            env => $env,
   172→            grammar => $grammar,
   173→            rule => $rule,
   174→            forest => $forest,
   175→            type => $inferred_type
   176→        );
   177→
   178→        return Chalk::Semiring::SemanticElement->new(
   179→            value => 1,  # Success value (not add_id which is 0)
   180→            context => $ctx
   181→        );
   182→    }
   183→
   184→    method multiply($x, $y) {
   185→        # For backward compatibility if called directly
   186→        return $x->multiply($y);
   187→    }
   188→
   189→    method plus($x, $y) {
   190→        # For backward compatibility if called directly
   191→        return $x->add($y);
   192→    }
   193→
   194→    # Infer the type of an expression from its grammar rule
   195→    method infer_type_from_rule($rule) {
   196→        return Chalk::Type::Any->new() unless defined($rule);
   197→
   198→        my $lhs = $rule->lhs;
   199→        my @rhs = @{$rule->rhs};
   200→
   201→        # Literal types - check RHS for terminal patterns
   202→        if (@rhs == 1) {
   203→            my $terminal = $rhs[0];
   204→            # Integer literal
   205→            return Chalk::Type::Int->new() if $terminal eq '%INTEGER%';
   206→            # Float/Number literal
   207→            return Chalk::Type::Num->new() if $terminal eq '%FLOAT%' || $terminal eq '%VERSION%';
   208→            # String literals
   209→            return Chalk::Type::Str->new() if $terminal eq '%SINGLE_QUOTED_STRING%'
   210→                                           || $terminal eq '%DOUBLE_QUOTED_STRING%';
   211→        }
   212→
   213→        # Variable types - infer from sigil in RHS
   214→        if ($lhs =~ qr/Variable$/) {
   215→            # Scalar variable: $ identifier
   216→            if (@rhs >= 1 && $rhs[0] eq '$') {
   217→                return Chalk::Type::Scalar->new();
   218→            }
   219→            # Array variable: @ identifier
   220→            if (@rhs >= 1 && $rhs[0] eq '@') {
   221→                return Chalk::Type::Array->new(
   222→                    element_type => Chalk::Type::Any->new()
   223→                );
   224→            }
   225→            # Hash variable: % identifier
   226→            if (@rhs >= 1 && $rhs[0] eq '%') {
   227→                return Chalk::Type::Hash->new(
   228→                    value_type => Chalk::Type::Any->new()
   229→                );
   230→            }
   231→        }
   232→
   233→        # Operation types - check for operators in RHS
   234→        for my $i (0 .. $#rhs) {
   235→            my $symbol = $rhs[$i];
   236→            # Numeric operations
   237→            if ($symbol =~ qr/^[+\-*\/]$/ || $symbol eq '**') {
   238→                return Chalk::Type::Num->new();
   239→            }
   240→            # String concatenation
   241→            if ($symbol eq '.') {
   242→                return Chalk::Type::Str->new();
   243→            }
   244→            # Range operator
   245→            if ($symbol eq '..') {
   246→                return Chalk::Type::List->new();
   247→            }
   248→        }
   249→
   250→        # Type inference by LHS name
   251→        return Chalk::Type::Int->new()    if $lhs eq 'Integer' || $lhs eq 'IntegerLiteral';
   252→        return Chalk::Type::Num->new()    if $lhs eq 'Number' || $lhs eq 'NumberLiteral';
   253→        return Chalk::Type::Str->new()    if $lhs eq 'String' || $lhs eq 'StringLiteral'
   254→                                          || $lhs =~ qr/Quoted/;
   255→        return Chalk::Type::Array->new(element_type => Chalk::Type::Any->new())
   256→                                       if $lhs eq 'ArrayLiteral' || $lhs eq 'List';
   257→        return Chalk::Type::List->new()   if $lhs eq 'Range';
   258→
   259→        # Default to Any for unknown constructs
   260→        return Chalk::Type::Any->new();
   261→    }
   262→}
   263→
   264→

