    63→    my $comp2 = Chalk::Semiring::CompositeElement->new(elements => [$bool2, $pos2]);
    64→
    65→    my $result = $comp1->add($comp2);
    66→
    67→    ok $result, 'Addition succeeds';
    68→    isa_ok $result, 'Chalk::Semiring::CompositeElement';
    69→
    70→    # Check Boolean addition (OR)
