    72→
    73→    # Check Position addition (prefers further)
    74→    is $result->elements->[1]->end_pos, 5, 'Position prefers further parse';
    75→};
    76→
    77→subtest 'CompositeElement to_string combines' => sub {
    78→    my $bool = Chalk::Semiring::BooleanElement->new(value => 1);
    79→    my $pos = Chalk::Semiring::PositionElement->new(start_pos => 0, end_pos => 5);
    80→
