    82→
    83→    my $str = $composite->to_string;
    84→    ok $str, 'to_string produces output';
    85→    like $str, qr/1/, 'Contains Boolean representation';
    86→    like $str, qr/\[0,5\]/, 'Contains Position representation';
    87→};
    88→
    89→subtest 'Composite semiring creation' => sub {
    90→    my $bool_sr = Chalk::Semiring::Boolean->new();
    91→    my $pos_sr = Chalk::Semiring::Position->new();
    92→
    93→    my $composite = Chalk::Semiring::Composite->new(
    94→        semirings => [$bool_sr, $pos_sr]
    95→    );
    96→
    97→    ok $composite, 'Composite semiring created';
    98→    is $composite->semirings, [$bool_sr, $pos_sr], 'Semirings accessor works';
    99→};
